# Display names for progress_categories - report_units.py-only categories
# (game_loop/actor/... don't mirror a src/ directory the way graphics/util/
# system do, so `category.capitalize()` alone would read oddly).
CATEGORY_NAMES = {
    "system": "System",
    "util": "Util",
    "graphics": "Graphics",
    "game_loop": "Game Loop",
    "actor": "Actor",
    "graphics_loading": "Graphics Loading",
    "audio": "Audio (GAX2)",
    "hud": "HUD",
    "overlay_ui": "Overlay UI",
}


def run(cmd, **kwargs):
    subprocess.run(cmd, check=True, **kwargs)


def slice_source(source, start, end):
    args = ["python3", str(ROOT / "tools" / "slice_expected.py"), str(source), f"{start:x}"]
    if end is not None:
        args.append(f"{end:x}")
    return subprocess.run(args, capture_output=True, text=True, check=True).stdout


def build_target(name, start, end):
    """Assembles the frozen-source slice(s) covering [start, end) into
    build/expected/units/<key>_target.o, applying corrections.txt.

    Filenames are keyed by `name` plus `start` (not `name` alone): several
    UNITS entries intentionally share one base_object (e.g. two matched
    functions split out of the same .c file, each with its own address
    range - see settings_menu8d.o/actor_part85.o) and used to collide on
    plain `{name}_target.o`, silently overwriting each other's expected
    bytes so only the last such entry's function was ever actually
    objdiff-verified. """
    key = f"{name}_{start:08X}"
    out_o = BUILD_DIR / f"{key}_target.o"
    if start < CODE3_START and (end is None or end <= CODE3_START):
        text = slice_source(LEGACY, start, end)
        out_s = BUILD_DIR / f"{key}_target.s"
        out_s.write_text(text)
        run(AS + ["-o", str(out_o), str(out_s)])
    elif start >= CODE3_START:
        text = slice_source(CODE3, start, end)
        out_s = BUILD_DIR / f"{key}_target.s"
        out_s.write_text(text)
        run(AS + ["-o", str(out_o), str(out_s)])
    else:
        # Straddles both frozen sources (only irq.c does) - slice each
        # half separately, then merge.
        legacy_text = slice_source(LEGACY, start, CODE3_START)
        code3_text = slice_source(CODE3, CODE3_START, end)
        legacy_s = BUILD_DIR / f"{key}_legacy.s"
        code3_s = BUILD_DIR / f"{key}_code3.s"
        legacy_s.write_text(legacy_text)
        code3_s.write_text(code3_text)
        legacy_o = BUILD_DIR / f"{key}_legacy.o"
        code3_o = BUILD_DIR / f"{key}_code3.o"
        run(AS + ["-o", str(legacy_o), str(legacy_s)])
        run(AS + ["-o", str(code3_o), str(code3_s)])
        run(LD + ["-o", str(out_o), str(legacy_o), str(code3_o)])

    run(["python3", str(ROOT / "tools" / "patch_expected_target.py"), str(CORRECTIONS), str(out_o)])
    return out_o


def main():
    BUILD_DIR.mkdir(parents=True, exist_ok=True)
    categories = {}
    units = []

    # Files with a leftover raw pointer-arithmetic offset cast or raw
    # hardware address (see chunk_remaining_work.py's scan_cleanup_candidates
    # / its "Cleanup: raw pointer arithmetic in ..." issues) are matched
    # but not yet cleaned up per docs/workflow.md step 7. A matched unit
    # not in this set gets metadata.complete=True; one that is gets
    # False - objdiff/decomp.dev track this as a status independent of
    # match percentage, so a byte-exact-but-uncleaned file still shows
    # 100% matched while correctly not counting as "complete".
    needs_cleanup = {entry["file"] for entry in scan_cleanup_candidates()}

    for i in range(len(UNITS) - 1):
        start, base_rel, category = UNITS[i]
        end = UNITS[i + 1][0]
        if base_rel is None:
            name = f"raw_{start:08X}"
        else:
            name = Path(base_rel).stem

        target_o = build_target(name, start, end)
        unit = {
            "name": name,
            "target_path": str(target_o.relative_to(ROOT)),
        }
        metadata = {}
        if base_rel is not None:
            unit["base_path"] = f"build/crashbandicootxs/{base_rel}"
            src_path = str(Path(base_rel).with_suffix(".c"))
            metadata["complete"] = src_path not in needs_cleanup
        if category is not None:
            metadata["progress_categories"] = [category]
            categories[category] = CATEGORY_NAMES.get(category, category.capitalize())
        if metadata:
            unit["metadata"] = metadata
        units.append(unit)

    objdiff = {
        "$schema": "https://raw.githubusercontent.com/encounter/objdiff/main/config.schema.json",
        "build_target": False,
        "build_base": False,
        "progress_categories": [{"id": cid, "name": name} for cid, name in categories.items()],
        "units": units,
    }
    (ROOT / "objdiff.json").write_text(json.dumps(objdiff, indent=4) + "\n")
    print(f"Wrote objdiff.json with {len(units)} units, {len(categories)} categories")


if __name__ == "__main__":
    main()
